 action="{{ route('admin.api-mutate') }}" @if($active) onsubmit="return confirm('Deactivate this coupon?');" @endif>@csrf<input type="hidden" name="_api_method" value="PATCH"><input type="hidden" name="_api_endpoint" value="/api/admin/promotions/coupons/{{ $couponId }}/status"><input type="hidden" name="Active" value="{{ $active?'false':'true' }}"><button class="rounded-lg border border-slate-200 px-3 py-2 text-xs font-semibold">{{ $active?'Deactivate':'Activate' }}</button></form></div></td></tr>@endforeach</tbody></table></div>@else<div class="px-5 py-12 text-center text-sm text-slate-500">No coupon records returned by PromotionService.</div>@endif</section>
<script>
(()=>{const form=document.querySelector('form[action="{{ route('admin.api-mutate') }}"]');if(!form)return;const type=form.elements.DiscountType;const value=form.elements.Value;const starts=form.elements.StartsAt;const ends=form.elements.EndsAt;const update=()=>{value.max=type.value==='Percent'?'100':'';value.setCustomValidity(type.value==='Percent'&&Number(value.value)>100?'Percentage discounts cannot exceed 100.':'');};type.addEventListener('change',update);value.addEventListener('input',update);form.addEventListener('submit',event=>{update();if(starts.value&&ends.value&&new Date(ends.value)<=new Date(starts.value)){event.preventDefault();ends.setCustomValidity('End date must be after start date.');ends.reportValidity();return;}ends.setCustomValidity('');if(!form.reportValidity())event.preventDefault();});ends.addEventListener('input',()=>ends.setCustomValidity(''));update();})();
</script>
